// Buyers directory: lower-middle and middle-market private equity firms, shown in every workspace.
// Generated by tools/build-funds.py from research checked against each firm's own website. Don't edit by hand.
export const FUNDS = [];
const BY_ID = new Map(FUNDS.map((f) => [f.id, f]));
export const fundById = (id) => BY_ID.get(id);
export const usdOf = (f) => [f.ebitda_min_usd, f.ebitda_max_usd];
